internal data class PlatformBrand(
    val label: String,
    val color: Color,
    val vector: ImageVector,
)

// 品牌色只标识平台，解锁状态由独立状态标记表达。
@Composable
internal fun PlatformIcon(brand: PlatformBrand, modifier: Modifier = Modifier) {
    Icon(brand.vector, contentDescription = brand.label, modifier = modifier, tint = brand.color)
}

internal object PlatformIcons {
    fun forPlatform(platform: String): PlatformBrand? = when (platform) {
