    // 原始 SVG 坐标不重写，居中到方形画布以免非方形品牌标识变形。
    private fun svg(name: String, width: Float, height: Float, outlined: Boolean, vararg paths: String): ImageVector {
        val side = maxOf(width, height)
        return ImageVector.Builder(name, 24.dp, 24.dp, side, side).apply {
            addGroup(translationX = (side - width) / 2, translationY = (side - height) / 2)
            paths.forEach { data ->
                addPath(
                    pathData = addPathNodes(data),
                    fill = if (outlined) null else SolidColor(Color.Black),
                    stroke = if (outlined) SolidColor(Color.Black) else null,
                    strokeLineWidth = 1f,
                    strokeLineCap = StrokeCap.Round,
                    strokeLineJoin = StrokeJoin.Round,
                )
            }
            clearGroup()
        }.build()
    }
